// Compiles tokens.json into CSS custom properties and a typed TS module (spec 10.2).
// Usage: node scripts/build.mjs [--check]   --check fails if generated files are stale.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const tokens = JSON.parse(readFileSync(join(root, 'tokens.json'), 'utf8'));
const check = process.argv.includes('--check');

const cssName = (key) => `--${key.replaceAll('.', '-')}`;
const resolve = (value) =>
  value.replace(/\{([^}]+)\}/g, (_, ref) => {
    const hit = tokens.primitive[ref];
    if (!hit) throw new Error(`Unknown primitive reference {${ref}}`);
    return hit;
  });

const block = (selector, entries) =>
  `${selector} {\n${Object.entries(entries)
    .map(([k, v]) => `  ${cssName(k)}: ${resolve(v)};`)
    .join('\n')}\n}\n`;

const { light, dark } = tokens.themes;
const lightKeys = Object.keys(light).sort().join();
if (lightKeys !== Object.keys(dark).sort().join()) throw new Error('Light and dark themes must define the same tokens');

const css = [
  '/* Generated by packages/tokens/scripts/build.mjs from tokens.json. Do not edit. */',
  block(':root', { ...tokens.scales, ...tokens.densities.comfortable, ...light }),
  block(":root[data-density='compact']", tokens.densities.compact),
  block(":root[data-theme='dark']", dark),
  `@media (prefers-color-scheme: dark) {\n${block(":root:not([data-theme='light'])", dark)
    .split('\n')
    .map((l) => (l ? `  ${l}` : l))
    .join('\n')}}\n`,
  ':root { color-scheme: light; }',
  ":root[data-theme='dark'] { color-scheme: dark; }",
  "@media (prefers-color-scheme: dark) { :root:not([data-theme='light']) { color-scheme: dark; } }",
  '',
].join('\n');

const allKeys = [...Object.keys(tokens.scales), ...Object.keys(tokens.densities.comfortable), ...Object.keys(light)];
const resolvedTheme = (t) => Object.fromEntries(Object.entries(t).map(([k, v]) => [k, resolve(v)]));
const ts = `// Generated by packages/tokens/scripts/build.mjs from tokens.json. Do not edit.
export type TokenName =\n${allKeys.map((k) => `  | '${k}'`).join('\n')};

export const themeValues = ${JSON.stringify({ light: resolvedTheme(light), dark: resolvedTheme(dark) }, null, 2)} as const;

export const contrastPairs = ${JSON.stringify(tokens.contrastPairs)} as ReadonlyArray<readonly [string, string, number]>;
`;

const outputs = [
  [join(root, 'src/generated/tokens.css'), css],
  [join(root, 'src/generated/tokens.ts'), ts],
];
let stale = false;
for (const [file, content] of outputs) {
  const current = existsSync(file) ? readFileSync(file, 'utf8') : '';
  if (current === content) continue;
  stale = true;
  if (!check) writeFileSync(file, content);
}
if (check && stale) {
  console.error('Design tokens are stale. Run: npm run tokens');
  process.exit(1);
}
console.log(check ? 'tokens up to date' : 'tokens built');
